'use strict';
const fs=require('fs'),path=require('path'),zlib=require('zlib'),{chromium}=require('playwright');const modes=process.argv.slice(2);if(!modes.length)modes.push('before','after','final');
(async()=>{const b=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']});for(const mode of modes){const out=path.resolve('docs/qa-posture-response-20261009',mode),html=zlib.gunzipSync(fs.readFileSync(path.join(out,'candidate-index.html.gz'))),states=[],checks=[];
for(const kind of ['horizontal','lathe'])for(const axis of kind==='horizontal'?['X','Y','Z']:['X','Z']){const p=await b.newPage({viewport:{width:1280,height:1000},reducedMotion:'reduce'});await p.route('http://demo.test/**',r=>r.fulfill({contentType:'text/html',body:html}));await p.goto('http://demo.test/');await p.evaluate(kind=>{openMachine(machines.find(m=>m.kind===kind));machineProfile=null;machineReference=null;machineSavedBest=null;positions={X:0,Y:0,Z:0,A:0,C:0};supportHeights=supports.map(()=>0);$('exaggerate').checked=false;updateAxisValues();updateLeveling(false);},kind);
const read=()=>p.evaluate(()=>({kind:current.kind,positions:{...positions},config:{...levelConfig},size:{w:current.w,d:current.d},labels:createGeometry(current).labels.map(l=>({name:l.name,point:displayedModelPoint(l.p,l.axes,current,positions,l.pose)}))}));const start=await read();await p.locator('#axisTabs .axis-tab').filter({hasText:axis+'軸'}).click();await p.locator('#openTrainingMenu').click();if(!await p.locator('#axisMenuSection').evaluate(e=>e.open))await p.locator('#axisMenuSection summary').click();const t=new Date('2026-10-10T12:00:00Z');await p.clock.install({time:t});await p.clock.pauseAt(new Date(t.getTime()+1000));await p.locator('#playAxis').click();await p.clock.runFor(650);const moved=await read();await p.locator('#openTrainingMenu').click({force:true});await p.locator('#playAxis').click({force:true});await p.locator('#closeTrainingMenu').click({force:true});await p.clock.resume();await p.screenshot({path:path.join(out,`demo-clock-${kind}-${axis}.png`)});const stopped=await read(),value=Math.round(stopped.positions[axis]);await p.locator('#openTrainingMenu').click();await p.locator('#axis-'+axis).fill(String(value));await p.locator('#axis-'+axis).dispatchEvent('input');await p.locator('#closeTrainingMenu').click();const replay=await read();
const moveNames=kind==='horizontal'?(axis==='X'?['コラム','主軸頭']:axis==='Y'?['主軸頭']:['パレット台','パレット']):(axis==='X'?['Xスライド','タレット','工具ホルダ','工具']:['往復台','Xスライド','タレット','工具ホルダ','工具']);const delta=kind==='horizontal'?(axis==='X'?[.55*start.config.width/(start.size.w*.8),0,0]:axis==='Y'?[0,.3,0]:[0,0,.45*start.config.depth/(start.size.d*.8)]):axis==='X'?[0,0,.35*start.config.depth/(start.size.d*.8)]:[.7*start.config.width/(start.size.w*.8),0,0];
checks.push({name:`${kind} ${axis} demo changed selected axis only`,ok:Math.abs(moved.positions[axis])>35&&Object.entries(moved.positions).every(([key,v])=>key===axis||v===0)});for(const l of start.labels){const m=moved.labels.find(x=>x.name===l.name),factor=moveNames.includes(l.name)?moved.positions[axis]/100:0,error=Math.hypot(...m.point.map((v,i)=>v-l.point[i]-delta[i]*factor));checks.push({name:`${kind} ${axis} ${l.name} mechanical motion`,ok:error<1e-9,error});const a=stopped.labels.find(x=>x.name===l.name),c=replay.labels.find(x=>x.name===l.name),roundDelta=moveNames.includes(l.name)?(value-stopped.positions[axis])/100:0,roundError=Math.hypot(...c.point.map((v,i)=>v-a.point[i]-delta[i]*roundDelta));checks.push({name:`${kind} ${axis} ${l.name} demo/slider same transform`,ok:roundError<1e-9,error:roundError});}states.push({kind,axis,start,moved,stopped,replay});await p.close();}
fs.writeFileSync(path.join(out,'demo-recheck.json'),JSON.stringify({method:'Actual play/stop buttons; Playwright clock runs 650 ms of real requestAnimationFrame callbacks before pausing for stop, avoiding wall-clock race',states,checks},null,2));console.log(mode,checks.length,'checks',checks.filter(c=>!c.ok));}await b.close();})().catch(e=>{console.error(e);process.exit(1);});
